// Real LOLA elevation generated by scripts/fetch-textures.mjs. The resolution is chosen there
// (ELEV_PPD: 16 px/deg ≈ 1.9 km/px, ~33 MB; 64 px/deg ≈ 474 m/px, ~530 MB). Everything here reads
// the grid size and resolution from moon_meta.json, so no code changes are needed to swap it.
// Loaded lazily the first time anything needs elevation.

import { TEXTURE_BASE } from '../scene/config.js';

let gridPromise = null;

export function loadElevation() {
  if (!gridPromise) {
    gridPromise = (async () => {
      const meta = await (await fetch(`${TEXTURE_BASE}moon_meta.json`)).json();
      const { file, width, height } = meta.elevation;
      // Older meta files (built before ELEV_PPD existed) are always ldem_16.
      const pixelsPerDegree = meta.elevation.pixelsPerDegree ?? width / 360;
      const resolutionM = meta.elevation.resolutionM ?? ((Math.PI * meta.radiusKm) / height) * 1000;
      const dataset = meta.elevation.dataset ?? `LOLA ldem_${pixelsPerDegree}`;
      const res = await fetch(TEXTURE_BASE + file);
      if (!res.ok) throw new Error(`Elevation grid missing (${res.status}). Run "npm run textures".`);
      const data = new Int16Array(await res.arrayBuffer());
      return makeGrid({ data, width, height, pixelsPerDegree, resolutionM, dataset });
    })();
    gridPromise.catch(() => (gridPromise = null));
  }
  return gridPromise;
}

/**
 * Wrap a raw Int16 equirectangular grid (row 0 = 90°N, col 0 = 180°W) as a sampler.
 * Shared with build scripts (scripts/fetch-site-terrain.mjs) that read the grid from disk.
 */
export function makeGrid({ data, width, height, pixelsPerDegree = width / 360, resolutionM, dataset = `LOLA ldem_${width / 360}` }) {
  return {
    width,
    height,
    pixelsPerDegree,
    resolutionM: resolutionM ?? ((Math.PI * 1737.4) / height) * 1000,
    dataset,
    data,
    sample: (lat, lon) => sample(data, width, height, lat, lon),
  };
}

/** Bilinear elevation in metres at (lat, lon). */
function sample(data, w, h, lat, lon) {
  const x = ((lon + 180) / 360) * w - 0.5;
  const y = Math.min(Math.max(((90 - lat) / 180) * h - 0.5, 0), h - 1);
  const x0 = Math.floor(x);
  const y0 = Math.floor(y);
  const fx = x - x0;
  const fy = y - y0;
  const y1 = Math.min(y0 + 1, h - 1);
  const xa = ((x0 % w) + w) % w;
  const xb = (xa + 1) % w;
  const a = data[y0 * w + xa];
  const b = data[y0 * w + xb];
  const c = data[y1 * w + xa];
  const d = data[y1 * w + xb];
  return (a * (1 - fx) + b * fx) * (1 - fy) + (c * (1 - fx) + d * fx) * fy;
}
